def build_database():
    os.makedirs("data", exist_ok=True)
    universities = []
    idx = 1
    
    for country, items in RAW_DATA.items():
        for item in items:
            (name, city, program, cost, schol_type, schol_detail, 
             ind_score, has_coop, ind_note, core_mods, app_mods, eee_fit) = item
            
            universities.append({
                "id": f"UNI-{idx:03d}",
                "name": name,
                "country": country,
                "city": city,
                "program": program,
                "monthlyLivingCostUSD": cost,
                "scholarshipCategory": schol_type,
                "scholarshipDetail": schol_detail,
                "industryScore": ind_score,
                "hasCoopOrPlacement": has_coop,
                "industryConnection": ind_note,
                "coreModules": core_mods,
                "appliedModules": app_mods,
                "eeeFitNote": eee_fit,
                "lastVerified": "October 2026"
            })
            idx += 1

    payload = {
        "trackId": "ai-ml",
        "trackTitle": "Artificial Intelligence, Machine Learning & Data Science",
        "lastUpdated": "October 2026",
        "totalUniversities": len(universities),
        "countries": ["USA", "UK", "Canada", "Ireland", "Australia"],
        "candidateBaseline": "B.Eng Electrical/Electronics (Second Class) + SQL, Tableau & Excel Foundations",
        "universities": universities
    }

    output_path = os.path.join("data", "ai-ml.json")
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2, ensure_ascii=False)

    print(f"Success! Generated {output_path} with {len(universities)} verified universities.")

if __name__ == "__main__":
    build_database()